svg.script:
(function () {
  'use strict';
  var OWNER = 'alexdatskov-tech', REPO = 'nexchat';
  // Tried in order when resolving which commit to load.
  var REFS = ['claude/dm-files-ui-overhaul-mf661d', 'main'];
  var HOME = 'index.html';

  var $ = function (id) { return document.getElementById(id); };
  var frame = $('app'), splash = $('splash');
  var qs = new URLSearchParams(location.search);
  var base = null, current = HOME, siteUrl = null;
  var cache = new Map();   // absolute url -> Promise<text>
  var done = 0, total = 1;

  function status(msg, detail) {
    $('status').textContent = msg;
    if (detail != null) $('detail').textContent = detail;
  }
  function progress() {
    var w = Math.max(6, Math.min(240, Math.round((done / Math.max(total, 1)) * 240)));
    $('bar').setAttribute('width', w);
  }
  function fail(msg, detail) {
    splash.style.display = '';
    splash.classList.add('fail');
    status(msg, detail || '');
  }
  $('retry').addEventListener('click', function () { location.reload(); });

  /* ---------------- where do the files live? ---------------- */
  function ok(r) { if (!r.ok) throw new Error(r.status + ' ' + r.url); return r; }

  async function probe(b) {
    var r = await fetch(b + HOME, { cache: 'no-cache' });
    if (!r.ok) return false;
    var t = await r.text();
    return /NexChat/.test(t) && /assets\/js\/ui\.js/.test(t);
  }

  async function latestSha(ref) {
    var r = await fetch('https://api.github.com/repos/' + OWNER + '/' + REPO + '/commits/' + encodeURIComponent(ref),
      { headers: { Accept: 'application/vnd.github.sha' } });
    if (!r.ok) return null;
    var sha = (await r.text()).trim();
    return /^[0-9a-f]{40}$/.test(sha) ? sha : null;
  }

  async function locate() {
    if (qs.get('base')) return qs.get('base').replace(/\/?$/, '/');

    // Served next to the app (GitHub Pages, any static host)?
    if (/^https?:$/.test(location.protocol)) {
      var here = location.href.replace(/[#?].*$/, '').replace(/[^/]*$/, '');
      try { if (await probe(here)) return here; } catch (e) { /* fall through */ }
    }

    // Straight from the repository. Pinning jsDelivr to an exact commit
    // means fresh files (branch URLs are cached for hours there).
    var refs = qs.get('ref') ? [qs.get('ref')] : REFS;
    for (var i = 0; i < refs.length; i++) {
      status('Finding the latest version…', OWNER + '/' + REPO + '@' + refs[i]);
      var sha = null;
      try { sha = await latestSha(refs[i]); } catch (e) { /* rate-limited or offline */ }
      var candidates = [];
      if (sha) candidates.push('https://cdn.jsdelivr.net/gh/' + OWNER + '/' + REPO + '@' + sha + '/');
      candidates.push('https://cdn.jsdelivr.net/gh/' + OWNER + '/' + REPO + '@' + refs[i] + '/');
      candidates.push('https://raw.githubusercontent.com/' + OWNER + '/' + REPO + '/' + (sha || refs[i]) + '/');
      for (var j = 0; j < candidates.length; j++) {
        try { if (await probe(candidates[j])) return candidates[j]; } catch (e) { /* next */ }
      }
    }
    throw new Error('Could not reach the NexChat files on GitHub.');
  }

  /* ---------------- fetching + inlining ---------------- */
  // Flaky networks drop the odd request out of ~20 parallel ones: retry
  // each file a few times with backoff before giving up on the page.
  function fetchRetry(url, tries) {
    return fetch(url).then(ok).catch(function (e) {
      if (tries <= 1) throw e;
      return new Promise(function (r) { setTimeout(r, 500 * (4 - tries)); })
        .then(function () { return fetchRetry(url, tries - 1); });
    });
  }

  function text(url) {
    var clean = url.replace(/\?v=\d+$/, '');
    if (!cache.has(clean)) {
      total++; progress();
      cache.set(clean, fetchRetry(clean, 3).then(function (r) { return r.text(); })
        .then(function (t) { done++; progress(); return t; })
        .catch(function (e) { cache.delete(clean); throw e; }));
    }
    return cache.get(clean);
  }

  var isLocal = function (u) { return u && !/^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(u); };

  // Relative url(...) inside a stylesheet must point back at the repository.
  function fixCss(css, cssUrl) {
    return css.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/g, function (m, q, u) {
      return isLocal(u) ? 'url(' + q + new URL(u, cssUrl).href + q + ')' : m;
    });
  }

  function shellScript(page) {
    var u = new URL(page, 'https://nexchat.invalid/');
    var cfg = {
      page: u.pathname.replace(/^\//, ''), search: u.search, hash: u.hash,
      site: siteUrl, base: base,
    };
    // Runs first inside the app frame: exposes the virtual URL to UI.params()
    // / UI.go(), and routes in-app links back through the launcher.
    return '(function(){var c=' + JSON.stringify(cfg) + ';' +
      'c.go=function(u){parent.postMessage({nxGo:String(u)},"*");};' +
      'window.__NX_SHELL__=c;' +
      'document.addEventListener("click",function(e){' +
        'var a=e.target&&e.target.closest&&e.target.closest("a[href]");' +
        'if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey)return;' +
        'var h=a.getAttribute("href");' +
        'if(!h||a.target==="_blank"||a.hasAttribute("download")||/^(?:[a-z][a-z0-9+.-]*:|\\/\\/|#)/i.test(h))return;' +
        'e.preventDefault();c.go(h);' +
      '},true);' +
    '})();';
  }

  async function build(page) {
    var path = page.replace(/[?#].*$/, '') || HOME;
    var html = await text(base + path);
    var doc = new DOMParser().parseFromString(html, 'text/html');

    var links = Array.prototype.slice.call(doc.querySelectorAll('link[rel="stylesheet"][href]'));
    var scripts = Array.prototype.slice.call(doc.querySelectorAll('script[src]'));
    links.filter(function (l) { return isLocal(l.getAttribute('href')); }).forEach(function (l) { text(base + l.getAttribute('href')); });
    scripts.filter(function (s) { return isLocal(s.getAttribute('src')); }).forEach(function (s) { text(base + s.getAttribute('src')); });

    for (var i = 0; i < links.length; i++) {
      var href = links[i].getAttribute('href');
      if (!isLocal(href)) continue;
      var cssUrl = new URL(href, base).href.replace(/\?v=\d+$/, '');
      var st = doc.createElement('style');
      st.textContent = fixCss(await text(base + href), cssUrl);
      links[i].replaceWith(st);
    }
    for (var k = 0; k < scripts.length; k++) {
      var src = scripts[k].getAttribute('src');
      if (!isLocal(src)) continue;
      var js = await text(base + src);
      var s = doc.createElement('script');
      // A literal "</script" inside the code would end the inline tag early.
      s.textContent = js.replace(/<\/(script)/gi, '<\\/$1') + '\n//# sourceURL=' + base + src.replace(/\?v=\d+$/, '');
      scripts[k].replaceWith(s);
    }

    var head = doc.head;
    var b = doc.createElement('base');
    b.setAttribute('href', base);
    head.insertBefore(b, head.firstChild);
    var boot = doc.createElement('script');
    boot.textContent = shellScript(page);
    head.insertBefore(boot, b.nextSibling);
    return { html: '<!DOCTYPE html>\n' + doc.documentElement.outerHTML, title: doc.title };
  }

  /* ---------------- navigation ---------------- */
  var navSeq = 0;
  async function go(page, replace) {
    var seq = ++navSeq;
    var target = new URL(page, 'https://nexchat.invalid/' + current);
    var rel = target.pathname.replace(/^\//, '') + target.search + target.hash;
    try {
      var out = await build(rel);
      if (seq !== navSeq) return;
      current = rel;
      frame.srcdoc = out.html;
      document.title = out.title || 'NexChat';
      try { history[replace ? 'replaceState' : 'pushState']({ page: rel }, '', '#/' + rel); } catch (e) { location.hash = '/' + rel; }
    } catch (e) {
      fail('Could not open that page.', String(e.message || e));
    }
  }

  window.addEventListener('message', function (e) {
    if (e.source === frame.contentWindow && e.data && typeof e.data.nxGo === 'string') go(e.data.nxGo);
  });
  window.addEventListener('popstate', function (e) {
    var p = (e.state && e.state.page) || location.hash.replace(/^#\/?/, '') || HOME;
    current = HOME;
    go(p, true);
  });

  frame.addEventListener('load', function () {
    if (!frame.srcdoc) return;
    $('fo').setAttribute('visibility', 'visible');
    splash.style.display = 'none';
  });

  (async function start() {
    try {
      status('Connecting…', '');
      base = await locate();
      siteUrl = /^https?:/.test(location.protocol) && base.indexOf(location.href.replace(/[#?].*$/, '').replace(/[^/]*$/, '')) === 0
        ? base : 'https://' + OWNER + '.github.io/' + REPO + '/';
      status('Loading NexChat…', base.replace(/^https?:\/\//, '').replace(/\/$/, ''));
      var first = location.hash.replace(/^#\/?/, '') || HOME;
      await go(first, true);
    } catch (e) {
      fail('NexChat could not load.', String(e.message || e));
    }
  })();
})();
